}

export async function verifyTipAndSave(
    paymentDetails: {
        razorpay_order_id: string;
        razorpay_payment_id: string;
        razorpay_signature: string;
    },
    tipDetails: {
        userName: string;
        userEmail: string;
        amount: number;
        note?: string;
    }
) {
    const { razorpay_order_id, razorpay_payment_id, razorpay_signature } = paymentDetails;

    // 1. Verify Signature
    const body = razorpay_order_id + "|" + razorpay_payment_id;
    const expectedSignature = crypto
        .createHmac('sha256', process.env.RAZORPAY_KEY_SECRET || '')
        .update(body.toString())
        .digest('hex');

    if (expectedSignature !== razorpay_signature) {
        return { success: false, error: 'Invalid payment signature' };
    }

    // 2. Save to Supabase
    const supabase = await createClient();
    const { error: dbError } = await supabase
        .from('cupcake_tips')
        .insert([{
            user_name: tipDetails.userName,
            user_email: tipDetails.userEmail,
            amount: tipDetails.amount,
            note: tipDetails.note,
            order_id: razorpay_order_id,
            payment_id: razorpay_payment_id
        }]);

    if (dbError) console.error('Supabase Insert Error:', dbError);

    // 3. Send Thank You Email to User via Resend
    try {
        const resend = new Resend(process.env.RESEND_API_KEY);
        await resend.emails.send({
            from: process.env.RESEND_FROM_EMAIL || 'support@avrxt.in',
            to: tipDetails.userEmail,
            subject: `A sweet note from avrxt 🧁`,
            html: `
                <div style="font-family: 'Outfit', sans-serif; max-width: 600px; margin: auto; padding: 40px; background: #000; color: #fff; border: 1px solid #333; border-radius: 20px; text-align: center;">
                    <div style="font-size: 50px; margin-bottom: 20px;">🧁</div>
                    <h1 style="background: linear-gradient(to right, #fff, #666); -webkit-background-clip: text; -webkit-text-fill-color: transparent; font-size: 32px; font-weight: 900; margin-bottom: 20px;">Thank You, ${tipDetails.userName}!</h1>
                    <p style="color: #aaa; font-size: 16px; line-height: 1.6; margin-bottom: 30px;">
                        Your support means the world to me. It's people like you who keep the creative engine running. 
                        I've received your sweet gesture of <strong>₹${tipDetails.amount}</strong>. 
                    </p>
                    <div style="padding: 20px; background: rgba(255,255,255,0.05); border-radius: 12px; font-style: italic; color: #fff; margin-bottom: 30px;">
                        "Architecture is built on support, and today, you are part of the foundation."
                    </div>
                    <p style="color: #444; font-size: 12px; text-transform: uppercase; letter-spacing: 2px;">Verified Transaction: ${razorpay_payment_id}</p>
                    <hr style="border: 0; border-top: 1px solid #222; margin: 30px 0;" />
                    <p style="font-weight: bold; color: #fff;">With 🖤 from avrxt</p>
                </div>
            `
        });
    } catch (e) { console.error('Resend Error:', e); }

    // 4. Send Notification to Admin via Nodemailer
    try {
        const transporter = nodemailer.createTransport({
            service: 'gmail',
            auth: { user: 'aviorxtaero@gmail.com', pass: process.env.GMAIL_APP_PASSWORD },
        });

        await transporter.sendMail({
            from: '"avrxt Cupcake" <aviorxtaero@gmail.com>',
            to: process.env.ADMIN_EMAIL,
            subject: `🧁 New Cupcake Received: ₹${tipDetails.amount} from ${tipDetails.userName}`,
            html: `
                <div style="font-family: monospace; background: #0a0a0a; color: #fff; padding: 30px; border-left: 4px solid #ff4785;">
                    <h2 style="color: #ff4785;">[CUPCAKE_ALIMENTATION_RECEIVED]</h2>
                    <p><strong>NAME:</strong> ${tipDetails.userName}</p>
                    <p><strong>EMAIL:</strong> ${tipDetails.userEmail}</p>
                    <p><strong>AMOUNT:</strong> ₹${tipDetails.amount}</p>
                    <p><strong>NOTE:</strong></p>
                    <div style="background: #111; padding: 15px; border-radius: 8px; color: #ff4785;">${tipDetails.note || "No note attached"}</div>
                    <p style="font-size: 10px; color: #444; margin-top: 20px;">SYSTEM_LOG: TX_${razorpay_payment_id}</p>
                </div>
            `
        });
    } catch (e) { console.error('Nodemailer Error:', e); }

    return { success: true };
}

export async function getRecentTips() {
    const supabase = await createClient();
    const { data } = await supabase
        .from('cupcake_tips')
        .select('user_name, created_at, amount')
        .order('created_at', { ascending: false })
        .limit(5);
    return data || [];
}

'use server';

import { createClient } from '@/utils/supabase/server';
import { revalidatePath } from 'next/cache';
import { DocArticle } from '@/lib/docs-config';
import { verifyAdmin } from '@/lib/auth-checks';

// Fetch all docs (Admin view - sees drafts too)
export async function getAdminDocs() {
    const { authorized } = await verifyAdmin();
    if (!authorized) return [];

    const supabase = await createClient();
    const { data, error } = await supabase
        .from('documents')
        .select('*')
        .order('created_at', { ascending: false });

    if (error) {
        console.error('Error fetching docs:', error);
        return [];
    }

    return data as DocArticle[];
}

// Fetch published docs (Public view)
export async function getPublishedDocs() {
    const supabase = await createClient();
    const { data, error } = await supabase
        .from('documents')
        .select('*')
        .eq('published', true)
        .order('created_at', { ascending: false });

    if (error) {
        console.error('Error fetching published docs:', error);
        return [];
    }

    return data as DocArticle[];
}

export async function getDocBySlug(slug: string) {
    const supabase = await createClient();
    const { data, error } = await supabase
        .from('documents')
        .select('*')
        .eq('slug', slug)
        .single(); // Assuming slug is unique

    if (error) {
        // console.error('Error fetching doc by slug:', error);
        return null;
    }

    return data as DocArticle;
}

export async function createDocAction(doc: Partial<DocArticle>) {
    const { authorized, error: authError } = await verifyAdmin();
    if (!authorized) {
        return { error: `Unauthorized: ${authError}` };
    }

    const supabase = await createClient();

    // Remove ID if present to let Supabase generate UUID
    const { id, ...docData } = doc;

    const { data, error } = await supabase
        .from('documents')
        .insert([{
            ...docData,
            created_at: new Date().toISOString(),
            last_modified: new Date().toISOString()
        }])
        .select()
        .single();

    if (error) {
        return { error: error.message };
    }

    revalidatePath('/docs');
    revalidatePath('/docs/admin');
    return { data };
}

export async function updateDocAction(id: string, updates: Partial<DocArticle>) {
    const { authorized, error: authError } = await verifyAdmin();
    if (!authorized) {
        return { error: `Unauthorized: ${authError}` };
    }

    const supabase = await createClient();

    const { data, error } = await supabase
        .from('documents')
        .update({
            ...updates,
            last_modified: new Date().toISOString()
        })
        .eq('id', id)
        .select()
        .single();

    if (error) {
        return { error: error.message };
    }

    revalidatePath('/docs');
    revalidatePath('/docs/admin');
    return { data };
}

export async function deleteDocAction(id: string) {
    const { authorized, error: authError } = await verifyAdmin();
    if (!authorized) {
        return { error: `Unauthorized: ${authError}` };
    }

    const supabase = await createClient();
    const { error } = await supabase.from('documents').delete().eq('id', id);

    if (error) {
        return { error: error.message };
    }

    revalidatePath('/docs');
    revalidatePath('/docs/admin');
    return { success: true };
}

'use server';

import { uploadFile, deleteFile, getPresignedUploadUrl } from '@/lib/r2';
import { verifyAdmin } from '@/lib/auth-checks';

export async function uploadToR2Action(formData: FormData, oldUrl?: string) {
    const { authorized, error: authError } = await verifyAdmin();
    if (!authorized) {
        return { error: `Unauthorized: ${authError}` };
    }

    const file = formData.get('file') as File;
    if (!file) return { error: 'No file provided' };

    // Organize images in /i and videos in /v as requested
    // Default to 'i', but check for video/audio types
    let folder: 'i' | 'v' = 'i';
    const cleanType = file?.type || '';
    const cleanName = file?.name || '';
    const isVideo = cleanType.startsWith('video/') || cleanName.match(/\.(mp4|webm|ogg|mov|m4v)$/i);
    const isAudio = cleanType.startsWith('audio/') || cleanName.match(/\.(mp3|wav|ogg|m4a|flac)$/i);

    if (isVideo || isAudio) {
        folder = 'v';
    }

    try {
        const arrayBuffer = await file.arrayBuffer();
        const buffer = Buffer.from(arrayBuffer);

        // Use a clean, timestamped filename
        const originalName = file.name.replace(/[^a-zA-Z0-9.]/g, '-');
        const fileExt = originalName.split('.').pop();
        const nameWithoutExt = originalName.split('.').slice(0, -1).join('.');
        const fileName = `${nameWithoutExt}-${Date.now()}.${fileExt}`;

        const publicUrl = await uploadFile(buffer, fileName, file.type, folder);

        // If there's an old file, delete it FROM R2
        if (oldUrl) {
            await deleteFile(oldUrl);
        }

        return { success: true, publicUrl };
    } catch (error: any) {
        console.error('R2 Upload Action Error:', error);
        return { error: error.message || 'R2_UPLOAD_FAILED' };
    }
}

export async function deleteFromR2Action(url: string) {
    const { authorized, error: authError } = await verifyAdmin();
    if (!authorized) {
        return { error: `Unauthorized: ${authError}` };
    }

    try {
        await deleteFile(url);
        return { success: true };
    } catch (error: any) {
        return { error: error.message || 'DELETE_FAILED' };
    }
}
export async function getPresignedR2UrlAction(fileName: string, fileType: string, oldUrl?: string) {
    const { authorized, error: authError } = await verifyAdmin();
    if (!authorized) {
        return { error: `Unauthorized: ${authError}` };
    }

    // Organize images in /i and videos in /v as requested
    let folder: 'i' | 'v' = 'i';
    const isVideo = (fileType || '').startsWith('video/') || fileName.match(/\.(mp4|webm|ogg|mov|m4v)$/i);
    const isAudio = (fileType || '').startsWith('audio/') || fileName.match(/\.(mp3|wav|ogg|m4a|flac)$/i);

    if (isVideo || isAudio) {
        folder = 'v';
    }

    try {
        // Use a clean, timestamped filename
        const cleanName = fileName.replace(/[^a-zA-Z0-9.]/g, '-');
        const fileExt = cleanName.split('.').pop();
        const nameWithoutExt = cleanName.split('.').slice(0, -1).join('.');
        const finalName = `${nameWithoutExt}-${Date.now()}.${fileExt}`;

        const cleanType = fileType || 'application/octet-stream';
        const data = await getPresignedUploadUrl(finalName, cleanType, folder);

        console.log(`[R2_PRESIGNED] Generated URL for ${finalName} in folder ${folder}`);

        return { success: true, ...data };
    } catch (error: any) {
        console.error('R2 Presigned URL Action Error:', error);
        return { error: error.message || 'R2_PRESIGNED_FAILED' };
    }
}

'use server';

const API_KEY = process.env.BETTERSTACK_API_KEY;
const STATUS_PAGE_ID = process.env.BETTERSTACK_STATUS_PAGE_ID;
const BASE_URL = 'https://uptime.betterstack.com/api/v2';

async function fetchBetterstack(endpoint: string) {
    if (!API_KEY) {
        throw new Error('BETTERSTACK_API_KEY is not configured');
    }

    const res = await fetch(`${BASE_URL}${endpoint}`, {
        headers: {
            'Authorization': `Bearer ${API_KEY}`,
            'Content-Type': 'application/json',
        },
        next: { revalidate: 60 } // Cache for 1 minute for faster sync
    });

    if (!res.ok) {
        const error = await res.text();
        console.error(`Betterstack API Error (${endpoint}):`, error);
        throw new Error(`Betterstack API responded with ${res.status}`);
    }

    return res.json();
}

// Map Betterstack aggregate_state values to our internal status
// Possible aggregate_state values per Betterstack API docs:
// "operational" | "degraded" | "partial_outage" | "major_outage" | "maintenance"
function mapAggregateState(state: string): { status: string; label: string } {
    switch (state) {
        case 'operational':
            return { status: 'operational', label: 'Systems Active' };
        case 'degraded':
        case 'degraded_performance':
            return { status: 'degraded', label: 'Performance Degraded' };
        case 'partial_outage':
            return { status: 'down', label: 'Partial Outage' };
        case 'major_outage':
            return { status: 'down', label: 'Major Outage' };
        case 'maintenance':
        case 'under_maintenance':
            return { status: 'maintenance', label: 'Ongoing Maintenance' };
        default:
            console.warn(`Unknown aggregate_state from Betterstack: "${state}"`);
            return { status: 'unknown', label: 'Status Unknown' };
    }
}

export async function getStatusOverview() {
    try {
        if (!STATUS_PAGE_ID) return { status: 'unknown', components: [] };

        // Fetch the status page itself — it contains "aggregate_state" which is
        // the official single source of truth for the overall page status.
        const page = await fetchBetterstack(`/status-pages/${STATUS_PAGE_ID}`);
        const aggregateState: string = page.data?.attributes?.aggregate_state ?? 'unknown';

        console.log(`[StatusBadge] Betterstack aggregate_state: "${aggregateState}"`);

        // Also fetch individual components for detail
        const resources = await fetchBetterstack(`/status-pages/${STATUS_PAGE_ID}/status-page-resources`);

        // Betterstack component status values are STRINGS:
        // "operational" | "degraded_performance" | "partial_outage" | "major_outage" | "under_maintenance"
        const components = resources.data.map((r: any) => ({
            name: r.attributes.public_name,
            status: r.attributes.status, // string value
            id: r.id
        }));

        const { status: globalStatus } = mapAggregateState(aggregateState);

        return {
            status: globalStatus,
            aggregateState,
            components,
            lastUpdated: new Date().toISOString()
        };
    } catch (error) {
        console.error('Failed to fetch status overview:', error);
        return { status: 'error', components: [], message: 'Connectivity failure to telemetry node' };
    }
}

export async function getMaintenanceSchedule() {
    try {
        if (!STATUS_PAGE_ID) return { maintenance: [] };

        const schedule = await fetchBetterstack(`/status-pages/${STATUS_PAGE_ID}/status-page-scheduled-maintenances`);

        return {
            maintenance: schedule.data.map((m: any) => ({
                id: m.id,
                title: m.attributes.title,
                status: m.attributes.status, // "upcoming" | "in_progress" | "completed" | "canceled"
                startsAt: m.attributes.starts_at,
                endsAt: m.attributes.ends_at,
                description: m.attributes.description
            }))
        };
    } catch (error) {
        console.error('Failed to fetch maintenance schedule:', error);
        return { maintenance: [] };
    }
}

export async function getStatusHistory() {
    try {
        if (!STATUS_PAGE_ID) return { incidents: [] };

        const history = await fetchBetterstack(`/status-pages/${STATUS_PAGE_ID}/status-page-reports`);

        return {
            incidents: history.data.map((i: any) => ({
                id: i.id,
                title: i.attributes.title,
                status: i.attributes.status,
                startedAt: i.attributes.starts_at,
                resolvedAt: i.attributes.ends_at,
                updates: i.attributes.updates || []
            }))
        };
    } catch (error) {
        console.error('Failed to fetch history:', error);
        return { incidents: [] };
    }
}

// Simple scraper fallback when no API key is configured
export async function getPublicStatus() {
    try {
        const res = await fetch('https://status.avrxt.in/badge?theme=dark', {
            next: { revalidate: 300 }
        });
        const html = await res.text();

        if (html.includes('Major outage')) {
            return { status: 'down', label: 'Major Outage' };
        } else if (html.includes('Partial outage') || html.includes('Some services are down')) {
            return { status: 'down', label: 'Partial Outage' };
        } else if (html.includes('Degraded') || html.includes('performance')) {
            return { status: 'degraded', label: 'Performance Degraded' };
        } else if (html.includes('Maintenance')) {
            return { status: 'maintenance', label: 'Ongoing Maintenance' };
        } else if (html.includes('All systems operational') || html.includes('operational')) {
            return { status: 'operational', label: 'Systems Active' };
        }

        return { status: 'operational', label: 'Systems Active' };
    } catch (error) {
        return { status: 'unknown', label: 'Status Unavailable' };
    }
}

// Primary function called by StatusBadge component
export async function getBetterstackStatus() {
    try {
        if (API_KEY && STATUS_PAGE_ID) {
            // Use the status page aggregate_state — the official Betterstack source of truth
            const page = await fetchBetterstack(`/status-pages/${STATUS_PAGE_ID}`);
            const aggregateState: string = page.data?.attributes?.aggregate_state ?? 'unknown';

            console.log(`[getBetterstackStatus] aggregate_state = "${aggregateState}"`);

            return mapAggregateState(aggregateState);
        }

        // Fallback to public scraping if no API credentials
        return getPublicStatus();
    } catch (error) {
        console.error('[getBetterstackStatus] Error:', error);
        return { status: 'unknown', label: 'Status Offline' };
    }
}

'use server'

import { createClient } from '@/utils/supabase/server';

export async function searchYouTubeAction(query: string) {
    // Admin-only: verify authentication
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return { error: 'Unauthorized' };

    const apiKey = process.env.YOUTUBE_API_KEY;
    if (!apiKey) return { error: 'YouTube API key not configured. Add YOUTUBE_API_KEY to your environment variables.' };

    try {
        const res = await fetch(
            `https://www.googleapis.com/youtube/v3/search?part=snippet&q=${encodeURIComponent(query)}&type=video&maxResults=10&key=${apiKey}`,
            { cache: 'no-store' }
        );

        if (!res.ok) {
            const err = await res.json();
            return { error: err.error?.message || 'YouTube API error' };
        }

        const data = await res.json();
        return data.items.map((item: any) => ({
            videoId: item.id.videoId,
            title: item.snippet.title,
            channelTitle: item.snippet.channelTitle,
            thumbnail: item.snippet.thumbnails.medium?.url || item.snippet.thumbnails.default?.url,
        }));
    } catch (err: any) {
        return { error: err.message };
    }
}

import { NextRequest, NextResponse } from 'next/server';
import nodemailer from 'nodemailer';
import { google } from 'googleapis';
import { getGooglePrivateKey } from '@/lib/google-key';

export async function POST(request: NextRequest) {
    try {
        const { name, email, message } = await request.json();

        if (!name || !email || !message) {
            return NextResponse.json(
                { error: 'Missing required fields' },
                { status: 400 }
            );
        }

        // --- 1. GOOGLE SHEETS AUTH ---
        let sheetSuccess = false;
        try {
            const privateKey = getGooglePrivateKey(process.env.GOOGLE_PRIVATE_KEY);
            const clientEmail = process.env.GOOGLE_SERVICE_ACCOUNT_EMAIL;
            const sheetId = process.env.GOOGLE_SHEET_ID;

            if (!privateKey || !clientEmail || !sheetId) {
                console.error('Missing Google Sheets credentials');
                // We don't return here, we just skip sheet logging so email can still be sent
            } else {
                const auth = new google.auth.GoogleAuth({
                    credentials: {
                        client_email: clientEmail,
                        private_key: privateKey,
                    },
                    scopes: ['https://www.googleapis.com/auth/spreadsheets'],
                });

                const sheets = google.sheets({ version: 'v4', auth });
                await sheets.spreadsheets.values.append({
                    spreadsheetId: sheetId,
                    range: 'Sheet1!A:D',
                    valueInputOption: 'USER_ENTERED',
                    requestBody: {
                        values: [[new Date().toLocaleString('en-IN'), name, email, message]],
                    },
                });
                sheetSuccess = true;
            }
        } catch (sheetError: unknown) {
            console.error('GOOGLE_SHEETS_ERROR:', sheetError);
            // Continue to email even if sheet fails
        }

        // --- 2. GMAIL SMTP NOTIFICATION ---
        if (process.env.GMAIL_APP_PASSWORD) {
            const transporter = nodemailer.createTransport({
                service: 'gmail',
                auth: {
                    user: 'aviorxtaero@gmail.com',
                    pass: process.env.GMAIL_APP_PASSWORD,
                },
            });

            await transporter.sendMail({
                from: `"avrxt Terminal" <aviorxtaero@gmail.com>`,
                to: 'irgtxpc@gmail.com',
                replyTo: email,
                subject: `🚨 NEW_SIGNAL: ${name}`,
                html: `
                    <div style="background:#000; color:#fff; font-family:monospace; padding:30px; border:1px solid #333;">
                        <h2 style="color:#666; font-size:14px; border-bottom:1px solid #222; padding-bottom:10px;">// INCOMING_PAYLOAD</h2>
                        <p style="margin:20px 0;"><strong>SENDER:</strong> ${name}</p>
                        <p style="margin:20px 0;"><strong>ADDRESS:</strong> ${email}</p>
                        <div style="background:#050505; border:1px solid #222; padding:15px; margin-top:20px; white-space:pre-wrap; color:#ccc; line-height:1.6;">
                            ${message}
                        </div>
                    </div>
                `,
            });
        }

        return NextResponse.json({
            success: true,
            message: 'Signal stored and transmitted.'
        });

    } catch (error: unknown) {
        console.error('CONTACT_API_ERROR:', error);
        const errorMessage = error instanceof Error ? error.message : 'Unknown error';
        return NextResponse.json(
            { error: 'SYSTEM_FAILURE', details: errorMessage },
            { status: 500 }
        );
    }
}

