'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
    BookOpen, Plus, Trash2, Save, LogOut, Edit2, Eye, Search,
    FileText, Check, Globe, Lock
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { DocArticle } from '@/lib/docs-config';
import { createDocAction, updateDocAction, deleteDocAction } from '@/app/actions/docs';
import { logout } from '@/app/actions/auth';

interface AdminClientProps {
    initialDocs: DocArticle[];
    userEmail: string;
}

export default function AdminClient({ initialDocs, userEmail }: AdminClientProps) {
    const [docs, setDocs] = useState<DocArticle[]>(initialDocs);
    const [selectedDoc, setSelectedDoc] = useState<Partial<DocArticle> | null>(null);
    const [isEditing, setIsEditing] = useState(false);
    const [saveStatus, setSaveStatus] = useState<string>('');
    const [searchQuery, setSearchQuery] = useState('');
    const [filterPublished, setFilterPublished] = useState<'all' | 'published' | 'draft'>('all');
    const [isPending, setIsPending] = useState(false);

    const router = useRouter();

    const handleSave = async () => {
        if (!selectedDoc) return;
        setIsPending(true);
        setSaveStatus('SYNCING...');

        try {
            let result;
            if (selectedDoc.id) {
                // Update existing
                result = await updateDocAction(selectedDoc.id, selectedDoc);
            } else {
                // Create new
                result = await createDocAction(selectedDoc);
            }

            if (result.error) {
                setSaveStatus(`ERROR: ${result.error}`);
            } else {
                setSaveStatus('SUCCESS: DOC_SYNCED');
                // Optimistic update or refetch
                // ideally we get the new doc back
                if (result.data) {
                    if (!selectedDoc.id) {
                        // If it was new, set ID and add to list
                        setDocs([result.data as DocArticle, ...docs]);
                        setSelectedDoc(result.data as DocArticle);
                    } else {
                        // Update list
                        setDocs(docs.map(d => d.id === result.data.id ? result.data as DocArticle : d));
                        setSelectedDoc(result.data as DocArticle);
                    }
                }

                setTimeout(() => setSaveStatus(''), 3000);
            }
        } catch (e) {
            setSaveStatus('SYSTEM_FAILURE');
        } finally {
            setIsPending(false);
        }
    };

    const handleDelete = async (id: string) => {
        if (confirm('Are you sure you want to delete this document? THIS CANNOT BE UNDONE.')) {
            setIsPending(true);
            await deleteDocAction(id);
            setDocs(docs.filter(d => d.id !== id));
            setSelectedDoc(null);
            setIsEditing(false);
            setIsPending(false);
        }
    };

    const handleNewDoc = () => {
        const newDoc: Partial<DocArticle> = {
            category: 'General',
            title: 'New Document',
            description: '',
            content: '# New Document\n\nStart writing your content here...',
            color: 'blue',
            published: false,
            tags: []
        };
        setSelectedDoc(newDoc);
        setIsEditing(true);
    };

    const filteredDocs = docs.filter(doc => {
        const matchesSearch = doc.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
            doc.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
            doc.category.toLowerCase().includes(searchQuery.toLowerCase());

        const matchesFilter = filterPublished === 'all' ||
            (filterPublished === 'published' && doc.published) ||
            (filterPublished === 'draft' && !doc.published);

        return matchesSearch && matchesFilter;
    });

    return (
        <main className="min-h-screen bg-[#0a0a0a] text-white selection:bg-white/10">
            {/* Header */}
            <header className="sticky top-0 z-50 border-b border-white/5 bg-[#0a0a0a]/80 backdrop-blur-xl">
                <nav className="max-w-[1800px] mx-auto px-6 h-auto min-h-16 py-4 flex flex-col md:flex-row justify-between items-center gap-4">
                    <div className="flex items-center gap-4 w-full md:w-auto overflow-x-auto pb-2 md:pb-0">
                        <BookOpen className="w-6 h-6 text-blue-500 flex-shrink-0" />
                        <h1 className="text-lg font-bold tracking-tighter uppercase font-mono whitespace-nowrap">Docs_Publisher</h1>
                        <span className="text-[10px] text-zinc-600 font-mono whitespace-nowrap">v3.0 (Supabase)</span>
                    </div>
                    <div className="flex flex-wrap items-center justify-center md:justify-end gap-3 w-full md:w-auto">
                        <span className="text-[10px] text-zinc-500 font-mono hidden lg:inline">
                            USER: {userEmail}
                        </span>
                        <Link
                            href="/docs"
                            target="_blank"
                            className="flex items-center gap-2 px-4 py-2 bg-zinc-800/50 hover:bg-zinc-700 text-zinc-400 hover:text-white rounded-full text-[10px] font-bold font-mono transition-all border border-white/5"
                        >
                            <Eye size={12} /> PREVIEW
                        </Link>
                        <Link
                            href="/me/admin"
                            className="flex items-center gap-2 px-4 py-2 bg-purple-900/20 hover:bg-purple-900/40 text-purple-400 hover:text-purple-300 rounded-full text-[10px] font-bold font-mono transition-all border border-purple-500/20"
                        >
                            PROFILE
                        </Link>
                        <button
                            onClick={handleSave}
                            disabled={isPending || !selectedDoc}
                            className="flex items-center gap-2 px-6 py-2 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 disabled:cursor-not-allowed text-white rounded-full text-xs font-bold font-mono transition-all shadow-[0_0_20px_rgba(59,130,246,0.3)]"
                        >
                            <Save size={14} /> {isPending ? 'SYNCING...' : 'SAVE'}
                        </button>
                        <button onClick={() => logout('/docs')} className="flex items-center gap-2 px-3 py-2 bg-zinc-800 hover:bg-zinc-700 text-white rounded-full text-xs font-bold font-mono transition-all">
                            <LogOut size={14} /> EXIT
                        </button>
                    </div>
                </nav>
            </header>

            {saveStatus && (
                <div className="fixed top-20 right-6 z-50 p-4 bg-emerald-500/10 border border-emerald-500/20 rounded-xl flex items-center gap-3 animate-in fade-in slide-in-from-top-2">
                    <Check className="text-emerald-500" size={16} />
                    <span className="text-[10px] font-mono text-emerald-500 uppercase">{saveStatus}</span>
                </div>
            )}

            <div className="max-w-[1800px] mx-auto p-6 flex flex-col lg:flex-row gap-6">
                {/* Sidebar - Document List */}
                <aside className="w-full lg:w-80 flex-shrink-0 space-y-4">
                    {/* Search & Filter */}
                    <div className="p-4 rounded-2xl bg-zinc-900/40 border border-white/5 space-y-3">
                        <div className="relative">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-500" />
                            <input
                                type="text"
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                placeholder="Search docs..."
                                className="w-full pl-10 pr-4 py-2 bg-black/40 border border-white/10 rounded-lg text-sm outline-none focus:border-blue-500/50 transition-all font-mono text-white"
                            />
                        </div>
                        <div className="flex gap-2">
                            {['all', 'published', 'draft'].map((filter) => (
                                <button
                                    key={filter}
                                    onClick={() => setFilterPublished(filter as any)}
                                    className={cn(
                                        "flex-1 px-3 py-1.5 rounded-lg text-[10px] font-mono uppercase transition-all",
                                        filterPublished === filter ? "bg-blue-600 text-white" : "bg-zinc-800 text-zinc-400 hover:bg-zinc-700"
                                    )}
                                >
                                    {filter === 'published' && <Globe className="w-3 h-3 inline mr-1" />}
                                    {filter === 'draft' && <Lock className="w-3 h-3 inline mr-1" />}
                                    {filter === 'all' ? 'All' : filter.charAt(0).toUpperCase() + filter.slice(1)}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* New Document Button */}
                    <button
                        onClick={handleNewDoc}
                        className="w-full p-4 rounded-2xl bg-blue-600 hover:bg-blue-500 text-white font-bold text-sm uppercase tracking-wider transition-all flex items-center justify-center gap-2 shadow-[0_0_20px_rgba(59,130,246,0.2)]"
                    >
                        <Plus size={18} /> New Document
                    </button>

                    {/* Document List */}
                    <div className="space-y-2 max-h-[calc(100vh-400px)] overflow-y-auto custom-scrollbar pr-2">
                        <div className="text-[10px] font-mono text-zinc-600 uppercase tracking-widest mb-3">
                            {filteredDocs.length} Document{filteredDocs.length !== 1 ? 's' : ''}
                        </div>
                        {filteredDocs.map((doc) => (
                            <button
                                key={doc.id}
                                onClick={() => {
                                    setSelectedDoc(doc);
                                    setIsEditing(false);
                                }}
                                className={cn(
                                    "w-full p-4 rounded-xl text-left transition-all border group",
                                    selectedDoc?.id === doc.id
                                        ? "bg-blue-600/20 border-blue-500/50"
                                        : "bg-zinc-900/40 border-white/5 hover:bg-zinc-800/60 hover:border-white/10"
                                )}
                            >
                                <div className="flex items-start justify-between mb-2">
                                    <h3 className="text-sm font-bold text-white line-clamp-1 flex-1">{doc.title}</h3>
                                    {doc.published ? (
                                        <Globe className="w-3 h-3 text-emerald-500 flex-shrink-0 ml-2" />
                                    ) : (
                                        <Lock className="w-3 h-3 text-orange-500 flex-shrink-0 ml-2" />
                                    )}
                                </div>
                                <p className="text-[10px] text-zinc-500 line-clamp-2 mb-2">{doc.description}</p>
                                <div className="flex items-center gap-2">
                                    <span className={cn(
                                        "text-[8px] px-2 py-0.5 rounded-full font-mono uppercase",
                                        doc.color === 'blue' && "bg-blue-900/30 text-blue-400 border border-blue-500/30",
                                        doc.color === 'cyan' && "bg-cyan-900/30 text-cyan-400 border border-cyan-500/30",
                                        doc.color === 'purple' && "bg-purple-900/30 text-purple-400 border border-purple-500/30",
                                        doc.color === 'green' && "bg-green-900/30 text-green-400 border border-green-500/30",
                                        doc.color === 'orange' && "bg-orange-900/30 text-orange-400 border border-orange-500/30",
                                        doc.color === 'pink' && "bg-pink-900/30 text-pink-400 border border-pink-500/30"
                                    )}>
                                        {doc.category}
                                    </span>
                                </div>
                            </button>
                        ))}
                    </div>
                </aside>

                {/* Main Content - Editor */}
                <section className="flex-1 min-w-0">
                    {selectedDoc ? (
                        <div className="space-y-6">
                            {/* Document Header */}
                            <div className="p-6 rounded-2xl bg-zinc-900/40 border border-white/5">
                                <div className="flex items-center justify-between mb-6">
                                    <h2 className="text-2xl font-bold font-mono uppercase tracking-tight">
                                        {isEditing ? 'Edit Document' : 'Document Preview'}
                                    </h2>
                                    <div className="flex items-center gap-2">
                                        {!isEditing && selectedDoc.id && (
                                            <>
                                                <button
                                                    onClick={() => setIsEditing(true)}
                                                    className="px-4 py-2 bg-zinc-800 hover:bg-zinc-700 text-white rounded-lg text-xs font-mono uppercase transition-all flex items-center gap-2"
                                                >
                                                    <Edit2 size={12} /> Edit
                                                </button>
                                                <button
                                                    onClick={() => handleDelete(selectedDoc.id!)}
                                                    className="px-4 py-2 bg-red-600/20 hover:bg-red-600/30 text-red-500 rounded-lg text-xs font-mono uppercase transition-all flex items-center gap-2 border border-red-500/30"
                                                >
                                                    <Trash2 size={12} /> Delete
                                                </button>
                                            </>
                                        )}
                                        {isEditing && (
                                            <button
                                                onClick={() => setIsEditing(false)}
                                                className="px-4 py-2 bg-zinc-800 hover:bg-zinc-700 text-white rounded-lg text-xs font-mono uppercase transition-all"
                                            >
                                                Cancel
                                            </button>
                                        )}
                                    </div>
                                </div>

                                {isEditing ? (
                                    <div className="grid grid-cols-2 gap-4">
                                        <div>
                                            <label className="text-[10px] text-zinc-500 uppercase tracking-widest mb-2 block">Title</label>
                                            <input
                                                type="text"
                                                value={selectedDoc.title}
                                                onChange={(e) => setSelectedDoc({ ...selectedDoc, title: e.target.value })}
                                                className="admin-input"
                                                placeholder="Document Title"
                                            />
                                        </div>
                                        <div>
                                            <label className="text-[10px] text-zinc-500 uppercase tracking-widest mb-2 block">Slug (URL)</label>
                                            <input
                                                type="text"
                                                value={selectedDoc.slug}
                                                onChange={(e) => setSelectedDoc({ ...selectedDoc, slug: e.target.value.toLowerCase().replace(/\s+/g, '-') })}
                                                className="admin-input"
                                                placeholder="document-slug"
                                            />
                                        </div>
                                        <div>
                                            <label className="text-[10px] text-zinc-500 uppercase tracking-widest mb-2 block">Category</label>
                                            <input
                                                type="text"
                                                value={selectedDoc.category}
                                                onChange={(e) => setSelectedDoc({ ...selectedDoc, category: e.target.value })}
                                                className="admin-input"
                                                placeholder="Category"
                                            />
                                        </div>
                                        <div>
                                            <label className="text-[10px] text-zinc-500 uppercase tracking-widest mb-2 block">Color Theme</label>
                                            <select
                                                value={selectedDoc.color}
                                                onChange={(e) => setSelectedDoc({ ...selectedDoc, color: e.target.value as any })}
                                                className="admin-input bg-black"
                                            >
                                                <option value="blue">Blue</option>
                                                <option value="cyan">Cyan</option>
                                                <option value="purple">Purple</option>
                                                <option value="green">Green</option>
                                                <option value="orange">Orange</option>
                                                <option value="pink">Pink</option>
                                            </select>
                                        </div>
                                        <div className="col-span-2">
                                            <label className="text-[10px] text-zinc-500 uppercase tracking-widest mb-2 block">Description</label>
                                            <textarea
                                                value={selectedDoc.description}
                                                onChange={(e) => setSelectedDoc({ ...selectedDoc, description: e.target.value })}
                                                className="admin-input min-h-[80px]"
                                                placeholder="Brief description..."
                                            />
                                        </div>
                                        <div className="col-span-2 flex items-center gap-4">
                                            <label className="flex items-center gap-2 cursor-pointer bg-zinc-800/50 p-4 rounded-xl border border-white/5 w-full">
                                                <input
                                                    type="checkbox"
                                                    checked={selectedDoc.published}
                                                    onChange={(e) => setSelectedDoc({ ...selectedDoc, published: e.target.checked })}
                                                    className="w-4 h-4 rounded bg-zinc-800 border-white/10 text-blue-600 focus:ring-blue-500"
                                                />
                                                <span className="text-sm font-mono text-white">Publish Document</span>
                                            </label>
                                        </div>
                                    </div>
                                ) : ( // Preview Mode
                                    <div className="space-y-4">
                                        <div className="flex items-center gap-3">
                                            <span className={cn(
                                                "text-[10px] px-3 py-1 rounded-full font-mono uppercase border",
                                                selectedDoc.color === 'blue' && "bg-blue-900/30 text-blue-400 border-blue-500/30",
                                                selectedDoc.color === 'cyan' && "bg-cyan-900/30 text-cyan-400 border-cyan-500/30",
                                                selectedDoc.color === 'purple' && "bg-purple-900/30 text-purple-400 border-purple-500/30",
                                                selectedDoc.color === 'green' && "bg-green-900/30 text-green-400 border-green-500/30",
                                                selectedDoc.color === 'orange' && "bg-orange-900/30 text-orange-400 border-orange-500/30",
                                                selectedDoc.color === 'pink' && "bg-pink-900/30 text-pink-400 border-pink-500/30"
                                            )}>
                                                {selectedDoc.category}
                                            </span>
                                            {selectedDoc.published ? (
                                                <span className="text-[10px] px-3 py-1 rounded-full font-mono uppercase bg-emerald-900/30 text-emerald-400 border border-emerald-500/30">
                                                    Published
                                                </span>
                                            ) : (
                                                <span className="text-[10px] px-3 py-1 rounded-full font-mono uppercase bg-orange-900/30 text-orange-400 border border-orange-500/30">
                                                    Draft
                                                </span>
                                            )}
                                        </div>
                                        <h1 className="text-3xl font-bold text-white">{selectedDoc.title}</h1>
                                        <p className="text-zinc-400">{selectedDoc.description}</p>
                                        <div className="flex items-center gap-4 text-[10px] text-zinc-600 font-mono">
                                            <span>Slug: /{selectedDoc.slug}</span>
                                            <span>•</span>
                                            <span>{selectedDoc.date}</span>
                                        </div>
                                    </div>
                                )}
                            </div>

                            {/* Content Editor */}
                            <div className="p-6 rounded-2xl bg-zinc-900/40 border border-white/5">
                                <div className="flex items-center justify-between mb-4">
                                    <h3 className="text-sm font-bold font-mono uppercase tracking-widest text-zinc-400">
                                        <FileText className="w-4 h-4 inline mr-2" />
                                        Content (Markdown)
                                    </h3>
                                    {isEditing && (
                                        <span className="text-[10px] text-zinc-600 font-mono">Supports Markdown formatting</span>
                                    )}
                                </div>
                                {isEditing ? (
                                    <textarea
                                        value={selectedDoc.content}
                                        onChange={(e) => setSelectedDoc({ ...selectedDoc, content: e.target.value })}
                                        className="admin-input min-h-[500px] font-mono text-sm"
                                        placeholder="# Your Document Title..."
                                    />
                                ) : (
                                    <div className="prose prose-invert max-w-none">
                                        <pre className="bg-black/40 p-6 rounded-xl border border-white/5 overflow-x-auto">
                                            <code className="text-sm text-zinc-300 font-mono">{selectedDoc.content}</code>
                                        </pre>
                                    </div>
                                )}
                            </div>
                        </div>
                    ) : (
                        <div className="h-[600px] flex items-center justify-center rounded-2xl bg-zinc-900/40 border border-white/5 border-dashed">
                            <div className="text-center">
                                <BookOpen className="w-16 h-16 mx-auto mb-4 text-zinc-700" />
                                <h3 className="text-xl font-bold text-zinc-600 mb-2 font-mono">No Document Selected</h3>
                                <p className="text-sm text-zinc-700 font-mono">Select a document from the sidebar or create a new one</p>
                            </div>
                        </div>
                    )}
                </section>
            </div>

            <style jsx global>{`
                .admin-input {
                    width: 100%;
                    padding: 0.75rem 1rem;
                    background: rgba(0,0,0,0.6);
                    border: 1px solid rgba(255,255,255,0.05);
                    border-radius: 0.75rem;
                    font-size: 0.875rem;
                    font-family: var(--font-mono);
                    outline: none;
                    transition: all 0.2s;
                    color: white;
                }
                .admin-input:focus {
                    border-color: rgba(59,130,246,0.5);
                    background: rgba(0,0,0,0.8);
                }
                .custom-scrollbar::-webkit-scrollbar {
                    width: 4px;
                }
                .custom-scrollbar::-webkit-scrollbar-track {
                    background: transparent;
                }
                .custom-scrollbar::-webkit-scrollbar-thumb {
                    background: rgba(255,255,255,0.1);
                    border-radius: 99px;
                }
            `}</style>
        </main>
    );
}

'use client';

import { useState, useEffect } from 'react';
import Link from 'next/link';
import { ArrowLeft, X } from 'lucide-react';
import { cn } from '@/lib/utils';

export default function Gallery() {
    const [selectedImg, setSelectedImg] = useState<string | null>(null);

    const images = [
        { id: '001', name: 'Thanjavur', src: 'https://objects.avrxt.in/images/aviorxt_01.jpg', description: 'When art, architecture, and divinity meet' },
        { id: '003', name: "The Wing's Edge", src: 'https://objects.avrxt.in/images/aviorxt_03.jpg' },
        { id: '005', name: '@Blue', src: 'https://objects.avrxt.in/images/aviorxt_05.jpg' },
        { id: '006', name: 'Artifact', src: 'https://objects.avrxt.in/images/aviorxt_06.jpg' },
    ];

    useEffect(() => {
        // Anti-save security protocols from original site
        const handleContextMenu = (e: MouseEvent) => e.preventDefault();
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.ctrlKey && (e.key === 's' || e.key === 'u' || e.key === 'p')) e.preventDefault();
            if (e.key === 'F12' || (e.ctrlKey && e.shiftKey && e.key === 'I')) e.preventDefault();
        };

        document.addEventListener('contextmenu', handleContextMenu);
        document.addEventListener('keydown', handleKeyDown);

        return () => {
            document.removeEventListener('contextmenu', handleContextMenu);
            document.removeEventListener('keydown', handleKeyDown);
        };
    }, []);

    return (
        <main className={cn(
            "min-h-screen bg-black text-white relative flex flex-col items-center",
            "font-outfit antialiased select-none"
        )}>
            {/* Background Decor */}
            <div className="fixed inset-0 pointer-events-none z-0">
                <div className="absolute inset-0 bg-[linear-gradient(to_right,rgba(255,255,255,0.02)_1px,transparent_1px),linear-gradient(to_bottom,rgba(255,255,255,0.02)_1px,transparent_1px)] bg-[size:60px_60px]"></div>
                <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-[0.15] mix-blend-soft-light"></div>
                <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_0%,#1a1a1a_0%,#000_75%)]"></div>
            </div>

            {/* Lightbox */}
            {selectedImg && (
                <div
                    className="fixed inset-0 z-[100] flex items-center justify-center bg-black/98 backdrop-blur-3xl transition-opacity duration-500 animate-in fade-in"
                    onClick={() => setSelectedImg(null)}
                >
                    <button className="absolute top-10 right-10 z-[120] text-zinc-500 hover:text-white transition-all">
                        <X className="w-8 h-8" />
                    </button>
                    <img
                        src={selectedImg}
                        alt="Vault View"
                        className="max-w-[90%] max-h-[80vh] rounded-sm transform transition-all duration-700 animate-in slide-in-from-bottom-5"
                    />
                </div>
            )}

            {/* Header */}
            <header className="relative z-30 w-full max-w-6xl mx-auto px-8 pt-12 flex justify-between items-center animate-fade-in">
                <Link href="/" className="flex items-center gap-4 group">
                    <div className="w-10 h-10 rounded-full bg-white/5 border border-white/10 flex items-center justify-center transition-all group-hover:bg-white/10">
                        <ArrowLeft className="w-4 h-4 text-zinc-400" />
                    </div>
                    <span className="font-mono text-[10px] uppercase tracking-[0.4em] text-zinc-500">System.Exit</span>
                </Link>
                <div className="flex flex-col items-end">
                    <span className="font-mono text-[10px] text-zinc-600 uppercase">Status</span>
                    <span className="text-[10px] text-emerald-500 font-mono animate-pulse tracking-widest">ENCRYPTED_NODE</span>
                </div>
            </header>

            {/* Content */}
            <section className="relative z-20 w-full max-w-6xl mx-auto px-8 pt-20 pb-32">
                <div className="mb-20 animate-fade-in" style={{ animationDelay: '0.2s' }}>
                    <span className="text-[11px] font-mono text-zinc-500 uppercase tracking-[0.3em]"># Visual_Archive_2025</span>
                    <h1 className="text-6xl md:text-8xl font-black tracking-tighter uppercase mb-6 italic" style={{ fontWeight: 900 }}>Vault</h1>
                    <p className="text-lg text-zinc-400 max-w-xl leading-relaxed font-light">
                        Secured artifacts from the digital frontier. Previews optimized for high-resolution displays.
                    </p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                    {images.map((img, i) => (
                        <div
                            key={img.id}
                            className="gallery-card group cursor-pointer rounded-xl overflow-hidden animate-fade-in"
                            style={{ animationDelay: `${0.4 + (i * 0.1)}s` }}
                            onClick={() => setSelectedImg(img.src)}
                        >
                            <div className="aspect-[16/10] overflow-hidden">
                                <img
                                    src={img.src}
                                    alt={img.name}
                                    className="w-full h-full object-cover transition-all duration-700 saturate-0 contrast-[1.2] group-hover:scale-105 group-hover:saturate-100 group-hover:contrast-100"
                                    onContextMenu={(e) => e.preventDefault()}
                                />
                            </div>
                            <div className="p-8 border-t border-white/5">
                                <div>
                                    <p className="text-[9px] font-mono text-zinc-600 uppercase tracking-widest mb-2">Ref. {img.id}</p>
                                    <h3 className="text-2xl font-bold tracking-tight uppercase text-white">{img.name}</h3>
                                    {img.description && (
                                        <p className="font-accent text-xl text-zinc-400 mt-2 italic">{img.description}</p>
                                    )}
                                </div>
                            </div>
                        </div>
                    ))}
                </div>

                <footer className="mt-40 pt-12 text-center border-t border-white/5">
                    <p className="text-[10px] text-zinc-700 font-mono uppercase tracking-[0.5em]">&copy; 2025 // AVRXT.IN // SILO_SECURED</p>
                </footer>
            </section>

            <style jsx>{`
        .font-outfit { font-family: 'Outfit', sans-serif; }
        .font-accent { font-family: 'Instrument Serif', serif; }
      `}</style>
        </main>
    );
}

'use client';

import { useState } from 'react';
import { User } from '@supabase/supabase-js';
import { Github, Send, Trash2, Edit3, X, Check } from 'lucide-react';
import { signInWithGithub, postMessage, deleteMessage, updateMessage } from '@/app/actions/guestbook';
import { cn } from '@/lib/utils';

interface Message {
    id: string;
    user_id: string;
    user_name: string;
    user_avatar: string;
    message: string;
    created_at: string;
}

export default function GuestbookClient({ user, initialMessages }: { user: User | null, initialMessages: Message[] }) {
    const [messages, setMessages] = useState<Message[]>(initialMessages);
    const [input, setInput] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [editInput, setEditInput] = useState('');

    const handleSignIn = () => {
        window.location.href = '/auth/login?source=guestbook';
    };

    const handleSignOut = async () => {
        const { logout } = await import('@/app/actions/auth');
        await logout('/guestbook');
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!input.trim() || !user) return;

        setIsSubmitting(true);
        // Better fallback for names and avatars
        const name = user.user_metadata.full_name || user.user_metadata.user_name || user.email?.split('@')[0] || 'Anonymous';
        const avatar = user.user_metadata.avatar_url || `https://ui-avatars.com/api/?name=${name}&background=random&color=fff`;

        const result = await postMessage(input, name, avatar);
        if (result.error) {
            alert(result.error);
        } else {
            setInput('');
            window.location.reload();
        }
        setIsSubmitting(false);
    };

    const handleDelete = async (id: string) => {
        if (!confirm('Are you sure you want to delete this message?')) return;
        const result = await deleteMessage(id);
        if (result.error) alert(result.error);
        else window.location.reload();
    };

    const handleUpdate = async (id: string) => {
        if (!editInput.trim()) return;
        const result = await updateMessage(id, editInput);
        if (result.error) alert(result.error);
        else {
            setEditingId(null);
            window.location.reload();
        }
    };

    return (
        <div className="space-y-12">
            {/* Auth/Post Section */}
            {!user ? (
                <div className="p-8 rounded-2xl bg-zinc-900/40 border border-white/5 backdrop-blur-md text-center">
                    <p className="text-zinc-400 mb-6 font-mono text-xs uppercase tracking-widest">Sign in to leave a message</p>
                    <button
                        onClick={handleSignIn}
                        className="inline-flex items-center gap-3 px-6 py-3 bg-white text-black rounded-xl font-bold hover:scale-105 transition-transform"
                    >
                        <Github size={18} />
                        Continue with GitHub
                    </button>
                </div>
            ) : (
                <div className="space-y-4">
                    <div className="flex items-center justify-between px-2">
                        <div className="flex items-center gap-2">
                            <img
                                src={user.user_metadata.avatar_url || `https://ui-avatars.com/api/?name=${user.email}&background=random`}
                                className="w-5 h-5 rounded-full border border-white/10"
                            />
                            <span className="text-[10px] font-mono text-zinc-500 uppercase tracking-widest">
                                Posting as <span className="text-zinc-300">{user.user_metadata.full_name || user.email}</span>
                            </span>
                        </div>
                        <button onClick={handleSignOut} className="text-[9px] font-mono text-zinc-600 hover:text-white uppercase transition-colors">
                            [ Sign_Out ]
                        </button>
                    </div>
                    <form onSubmit={handleSubmit} className="p-1 gap-2 flex flex-col sm:flex-row items-stretch">
                        <input
                            type="text"
                            value={input}
                            onChange={(e) => setInput(e.target.value)}
                            placeholder="Type your message..."
                            className="flex-1 bg-zinc-900/50 border border-white/5 rounded-xl px-4 py-3 outline-none focus:border-white/20 transition-all font-mono text-sm"
                            maxLength={200}
                        />
                        <button
                            type="submit"
                            disabled={isSubmitting || !input.trim()}
                            className="px-6 py-3 bg-white text-black rounded-xl font-bold hover:shadow-[0_0_20px_rgba(255,255,255,0.2)] transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 shrink-0"
                        >
                            {isSubmitting ? '...' : <><Send size={16} /> Post</>}
                        </button>
                    </form>
                </div>
            )}

            {/* Messages List */}
            <div className="space-y-6">
                {messages.length === 0 ? (
                    <p className="text-center text-zinc-600 font-mono text-xs py-10 tracking-[0.3em] uppercase">No messages yet. Be the first!</p>
                ) : (
                    messages.map((msg) => (
                        <div key={msg.id} className="group p-6 rounded-2xl bg-zinc-900/20 border border-white/5 hover:border-white/10 transition-all">
                            <div className="flex items-start gap-4">
                                <img src={msg.user_avatar} alt="" className="w-10 h-10 rounded-full border border-white/10" />
                                <div className="flex-1 min-w-0">
                                    <div className="flex items-center justify-between mb-1">
                                        <h4 className="text-sm font-bold font-mono text-white truncate">{msg.user_name}</h4>
                                        <span className="text-[10px] text-zinc-600 font-mono">
                                            {new Date(msg.created_at).toLocaleDateString()}
                                        </span>
                                    </div>

                                    {editingId === msg.id ? (
                                        <div className="space-y-2 mt-2">
                                            <textarea
                                                value={editInput}
                                                onChange={(e) => setEditInput(e.target.value)}
                                                className="w-full bg-black/50 border border-white/10 rounded-lg p-3 text-sm outline-none focus:border-white/30"
                                                rows={2}
                                            />
                                            <div className="flex gap-2">
                                                <button onClick={() => handleUpdate(msg.id)} className="p-2 bg-emerald-500/10 text-emerald-500 rounded-lg hover:bg-emerald-500/20 transition-colors">
                                                    <Check size={14} />
                                                </button>
                                                <button onClick={() => setEditingId(null)} className="p-2 bg-red-500/10 text-red-500 rounded-lg hover:bg-red-500/20 transition-colors">
                                                    <X size={14} />
                                                </button>
                                            </div>
                                        </div>
                                    ) : (
                                        <p className="text-zinc-400 text-sm leading-relaxed">{msg.message}</p>
                                    )}

                                    {/* Actions for owner */}
                                    {user?.id === msg.user_id && editingId !== msg.id && (
                                        <div className="flex gap-3 mt-4 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <button
                                                onClick={() => {
                                                    setEditingId(msg.id);
                                                    setEditInput(msg.message);
                                                }}
                                                className="text-[10px] font-mono uppercase text-zinc-500 hover:text-white flex items-center gap-1"
                                            >
                                                <Edit3 size={10} /> Edit
                                            </button>
                                            <button
                                                onClick={() => handleDelete(msg.id)}
                                                className="text-[10px] font-mono uppercase text-zinc-500 hover:text-red-500 flex items-center gap-1"
                                            >
                                                <Trash2 size={10} /> Delete
                                            </button>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>
                    ))
                )}
            </div>
        </div>
    );
}

