    const toggleModule = (id: string, price: number, weeks: number) => {
        if (selectedModules.includes(id)) {
            setSelectedModules(selectedModules.filter(m => m !== id));
            setTotalPrice(prev => prev - price);
            setTotalWeeks(prev => prev - weeks);
        } else {
