'use client';

import { useEffect, useRef, useState } from 'react';
import { cn } from '@/lib/utils';

interface RevealProps {
    children: React.ReactNode;
    className?: string;
    id?: string;
    style?: React.CSSProperties;
}

export default function Reveal({ children, className, id, style }: RevealProps) {
    const [isVisible, setIsVisible] = useState(false);
    const [isOut, setIsOut] = useState(false);
    const ref = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const observer = new IntersectionObserver(
            (entries) => {
                entries.forEach((entry) => {
                    if (entry.isIntersecting) {
                        setIsVisible(true);
                        setIsOut(false);
                    } else {
                        if (entry.boundingClientRect.top > 0) {
                            setIsVisible(false);
                            setIsOut(true);
                        }
                    }
                });
            },
            { threshold: 0.1, rootMargin: '0px 0px -50px 0px' }
        );

        if (ref.current) {
            observer.observe(ref.current);
        }

        return () => {
            if (ref.current) {
                observer.unobserve(ref.current);
            }
        };
    }, []);

    return (
        <div
            id={id}
            ref={ref}
            style={style}
            className={cn("reveal", isVisible && "active", isOut && "out", className)}
        >
            {children}
        </div>
    );
}

import { createAdminClient } from '@/utils/supabase/admin';

const client_id = process.env.SPOTIFY_CLIENT_ID;
const client_secret = process.env.SPOTIFY_CLIENT_SECRET;
const basic = Buffer.from(`${client_id}:${client_secret}`).toString('base64');
const NOW_PLAYING_ENDPOINT = `https://api.spotify.com/v1/me/player/currently-playing`;
const TOKEN_ENDPOINT = `https://accounts.spotify.com/api/token`;

export async function getSpotifyTokens() {
    const supabase = createAdminClient();
    const { data: tokens, error } = await supabase
        .from('spotify_tokens')
        .select('*')
        .single();

    if (error || !tokens) return null;
    return tokens;
}

export async function refreshAccessToken(refresh_token: string) {
    const response = await fetch(TOKEN_ENDPOINT, {
        method: 'POST',
        headers: {
            Authorization: `Basic ${basic}`,
            'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: new URLSearchParams({
            grant_type: 'refresh_token',
            refresh_token,
        }),
    });

    const data = await response.json();
    if (!response.ok) throw new Error('Failed to refresh token');

    const supabase = createAdminClient();
    const { error: updateError } = await supabase
        .from('spotify_tokens')
        .update({
            access_token: data.access_token,
            expires_at: new Date(Date.now() + data.expires_in * 1000).toISOString(),
        })
        .match({ refresh_token });

    if (updateError) console.error('Error updating tokens in DB:', updateError);

    return data.access_token;
}

export async function getNowPlaying() {
    const tokens = await getSpotifyTokens();
    if (!tokens) return { isPlaying: false };

    let accessToken = tokens.access_token;
    const expiresAt = new Date(tokens.expires_at).getTime();

    if (Date.now() > expiresAt - 60000) {
        accessToken = await refreshAccessToken(tokens.refresh_token);
    }

    const response = await fetch(NOW_PLAYING_ENDPOINT, {
        headers: {
            Authorization: `Bearer ${accessToken}`,
        },
    });

    if (response.status === 204 || response.status > 400) {
        return { isPlaying: false };
    }

    const song = await response.json();

    // Save to history if playing
    if (song.is_playing) {
        const supabase = createAdminClient();
        await supabase.from('spotify_history').upsert({
            song_name: song.item.name,
            artist: song.item.artists.map((_artist: any) => _artist.name).join(', '),
            cover_url: song.item.album.images[0].url,
            played_at: new Date().toISOString()
        }, { onConflict: 'song_name, artist' });
    }

    return {
        isPlaying: song.is_playing,
        title: song.item.name,
        artist: song.item.artists.map((_artist: any) => _artist.name).join(', '),
        album: song.item.album.name,
        albumImageUrl: song.item.album.images[0].url,
        songUrl: song.item.external_urls.spotify,
        progressMs: song.progress_ms,
        durationMs: song.item.duration_ms,
    };
}
export async function searchSpotify(query: string) {
    const tokens = await getSpotifyTokens();
    if (!tokens) return null;

    let accessToken = tokens.access_token;
    const expiresAt = new Date(tokens.expires_at).getTime();

    if (Date.now() > expiresAt - 60000) {
        accessToken = await refreshAccessToken(tokens.refresh_token);
    }

    const response = await fetch(`https://api.spotify.com/v1/search?q=${encodeURIComponent(query)}&type=track&limit=10`, {
        headers: {
            Authorization: `Bearer ${accessToken}`,
        },
    });

    if (!response.ok) return null;

    const data = await response.json();
    return data.tracks.items.map((track: any) => ({
        id: track.id,
        name: track.name,
        artist: track.artists.map((a: any) => a.name).join(', '),
        album: track.album.name,
        coverUrl: track.album.images[0]?.url,
        previewUrl: track.preview_url,
        spotifyUrl: track.external_urls.spotify,
    }));
}

import { createServerClient } from '@supabase/ssr'
import { NextResponse, type NextRequest } from 'next/server'

export async function updateSession(request: NextRequest) {
    let supabaseResponse = NextResponse.next({
        request,
    })

    const supabase = createServerClient(
        process.env.NEXT_PUBLIC_SUPABASE_URL!,
        process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
        {
            cookies: {
                getAll() {
                    return request.cookies.getAll()
                },
                setAll(cookiesToSet) {
                    cookiesToSet.forEach(({ name, value, options }) =>
                        request.cookies.set(name, value)
                    )
                    supabaseResponse = NextResponse.next({
                        request,
                    })
                    cookiesToSet.forEach(({ name, value, options }) =>
                        supabaseResponse.cookies.set(name, value, options)
                    )
                },
            },
        }
    )

    // Do not run Supabase code on static files to avoid unnecessary processing
    if (
        !request.nextUrl.pathname.startsWith('/_next') &&
        !request.nextUrl.pathname.startsWith('/api') &&
        !request.nextUrl.pathname.startsWith('/static')
    ) {
        await supabase.auth.getUser()
    }

    return supabaseResponse
}
